import random
from collections import deque
random.seed(4)

class MaxQueue:
    def __init__(self):
        self.inbox = []      # entries (value, max of this stack up to here)
        self.outbox = []

    def enqueue(self, x):
        m = x if not self.inbox else max(x, self.inbox[-1][1])
        self.inbox.append((x, m))

    def dequeue(self):
        if not self.outbox:
            while self.inbox:
                x, _ = self.inbox.pop()
                m = x if not self.outbox else max(x, self.outbox[-1][1])
                self.outbox.append((x, m))
        return self.outbox.pop()[0]

    def maximum(self):
        tops = [s[-1][1] for s in (self.inbox, self.outbox) if s]
        return max(tops)

cases = 0
for _ in range(300):
    q, ref = MaxQueue(), deque()
    for _ in range(random.randint(1, 40)):
        if ref and random.random() < 0.4:
            assert q.dequeue() == ref.popleft()
        else:
            x = random.randint(-5, 9)
            q.enqueue(x)
            ref.append(x)
        if ref:
            assert q.maximum() == max(ref)
    cases += 1
print('ok', cases)

import random
random.seed(8)

class Node:
    def __init__(self, key):
        self.key, self.left, self.right = key, None, None
        self.h, self.size = 0, 1

def h(v): return -1 if v is None else v.h
def size(v): return 0 if v is None else v.size

def update(v):
    v.h = 1 + max(h(v.left), h(v.right))
    v.size = size(v.left) + size(v.right) + 1       # the only new line compared with plain AVL

def rot_right(y):
    x = y.left
    y.left, x.right = x.right, y
    update(y)                                       # lower node first
    update(x)                                       # then the new top
    return x

def rot_left(x):
    y = x.right
    x.right, y.left = y.left, x
    update(x)
    update(y)
    return y

def rebalance(v):
    update(v)
    if h(v.left) - h(v.right) > 1:
        if h(v.left.left) < h(v.left.right):
            v.left = rot_left(v.left)
        return rot_right(v)
    if h(v.right) - h(v.left) > 1:
        if h(v.right.right) < h(v.right.left):
            v.right = rot_right(v.right)
        return rot_left(v)
    return v

def insert(v, key):
    if v is None:
        return Node(key)
    if key < v.key:
        v.left = insert(v.left, key)
    elif key > v.key:
        v.right = insert(v.right, key)
    return rebalance(v)

def delete(v, key):
    if v is None:
        return None
    if key < v.key:
        v.left = delete(v.left, key)
    elif key > v.key:
        v.right = delete(v.right, key)
    else:
        if v.left is None:
            return v.right
        if v.right is None:
            return v.left
        s = v.right
        while s.left:
            s = s.left
        v.key = s.key
        v.right = delete(v.right, s.key)
    return rebalance(v)

def rank(root, x):                 # number of keys smaller than x
    r, v = 0, root
    while v:
        if x <= v.key:
            v = v.left
        else:
            r += size(v.left) + 1
            v = v.right
    return r

def select(root, k):               # k-th smallest, k from 1
    v = root
    while True:
        s = size(v.left)
        if k == s + 1:
            return v.key
        if k <= s:
            v = v.left
        else:
            k -= s + 1
            v = v.right

def check(v):
    if v is None:
        return 0
    a, b = check(v.left), check(v.right)
    assert abs(h(v.left) - h(v.right)) <= 1
    assert v.size == a + b + 1
    return v.size

root, ref = None, set()
ops = 0
for _ in range(1500):
    x = random.randint(0, 60)
    if random.random() < 0.6:
        root = insert(root, x); ref.add(x)
