import random
random.seed(9)

def hubs(n, edges):
    g = [[] for _ in range(n)]
    gr = [[] for _ in range(n)]
    for u, v in edges:
        g[u].append(v)
        gr[v].append(u)
    seen, order = [False] * n, []
    def dfs(u):
        seen[u] = True
        for v in g[u]:
            if not seen[v]:
                dfs(v)
        order.append(u)          # appended when finished
    for u in range(n):
        if not seen[u]:
            dfs(u)
    r = order[-1]                # the largest finish time
    def reach(adj, s):
        mark, stack = {s}, [s]
        while stack:
            u = stack.pop()
            for v in adj[u]:
                if v not in mark:
                    mark.add(v)
                    stack.append(v)
        return mark
    if len(reach(g, r)) < n:
        return []
    return sorted(reach(gr, r))

def brute(n, edges):
    g = [[] for _ in range(n)]
    for u, v in edges:
        g[u].append(v)
    out = []
    for h in range(n):
        mark, stack = {h}, [h]
        while stack:
            u = stack.pop()
            for v in g[u]:
                if v not in mark:
                    mark.add(v)
                    stack.append(v)
        if len(mark) == n:
            out.append(h)
    return out

