import heapq, random
random.seed(3)

def cheapest(n, roads, k, s, t):
    adj = [[] for _ in range(n)]
    for u, v, w in roads:
        adj[u].append((v, w))
        adj[v].append((u, w))
    INF = float('inf')
    dist = {(s, 0): 0}
    heap = [(0, s, 0)]
    done = set()
    while heap:
        d, u, c = heapq.heappop(heap)
        if (u, c) in done:
            continue
        done.add((u, c))
        for v, w in adj[u]:
            for nc, cost in ((c, w), (c + 1, w // 2)):
                if nc <= k and d + cost < dist.get((v, nc), INF):
                    dist[(v, nc)] = d + cost
                    heapq.heappush(heap, (d + cost, v, nc))
    return min(dist.get((t, c), INF) for c in range(k + 1))

def brute(n, roads, k, s, t):
    adj = [[] for _ in range(n)]
    for u, v, w in roads:
        adj[u].append((v, w))
        adj[v].append((u, w))
    best = [float('inf')]
    def go(u, seen, ws):
        if u == t:
            saves = sorted((w - w // 2 for w in ws), reverse=True)[:k]
            best[0] = min(best[0], sum(ws) - sum(saves))
            return
        for v, w in adj[u]:
            if v not in seen:
                go(v, seen | {v}, ws + [w])
    go(s, {s}, [])
    return best[0]

