random.seed(11)

def greedy(xs, r):
    xs = sorted(xs)
    i, routers = 0, []
    while i < len(xs):
        p = xs[i] + r                     # leftmost unserved house: put the router r to its right
        routers.append(p)
        while i < len(xs) and xs[i] <= p + r:
            i += 1
    return routers

def served(xs, routers, r):
    return all(any(abs(x - p) <= r for p in routers) for x in xs)

def brute(xs, r):
    spots = range(min(xs) - r, max(xs) + r + 1)
    for k in range(1, len(xs) + 1):
        for combo in itertools.combinations(spots, k):
            if served(xs, combo, r):
                return k

